#!/usr/bin/env python3
"""Generate Global Crude Oil Price Trends Report (1970-2026)."""

import pandas as pd
import numpy as np
import json
from datetime import datetime
from pathlib import Path

# ── Load & prepare data ──────────────────────────────────────────────────────

df = pd.read_csv('/app/benchmark/data.csv', parse_dates=['Date'])
df = df.sort_values('Date').reset_index(drop=True)
df['Year'] = df['Date'].dt.year
df['Month'] = df['Date'].dt.month
df['Decade'] = (df['Year'] // 10) * 10
df['Price'] = df['Crude_Oil_Price']

# ── Helper ───────────────────────────────────────────────────────────────────

def fmt(n, decimals=2):
    return f"{n:,.{decimals}f}"

def pct(n):
    return f"{n:+.2f}%"

# ── KPI Calculations ────────────────────────────────────────────────────────

price_min = df['Price'].min()
price_max = df['Price'].max()
price_range = price_max - price_min
price_mean = df['Price'].mean()
price_median = df['Price'].median()
price_std = df['Price'].std()
price_p25 = df['Price'].quantile(0.25)
price_p75 = df['Price'].quantile(0.75)

# CAGR: (final/initial)^(1/years) - 1
first_price = df['Price'].iloc[0]
last_price = df['Price'].iloc[-1]
first_date = df['Date'].iloc[0]
last_date = df['Date'].iloc[-1]
days = (last_date - first_date).days
years = days / 365.25
cagr = ((last_price / first_price) ** (1 / years) - 1) * 100

# Month-over-month changes
df['MoM_Abs'] = df['Price'].diff()
df['MoM_Pct'] = df['Price'].pct_change() * 100
max_mom_abs = df['MoM_Abs'].max()
max_mom_abs_idx = df['MoM_Abs'].idxmax()
max_mom_abs_date = df.loc[max_mom_abs_idx, 'Date']
max_mom_pct = df['MoM_Pct'].max()
max_mom_pct_idx = df['MoM_Pct'].idxmax()
max_mom_pct_date = df.loc[max_mom_pct_idx, 'Date']
min_mom_abs = df['MoM_Abs'].min()
min_mom_abs_idx = df['MoM_Abs'].idxmin()
min_mom_abs_date = df.loc[min_mom_abs_idx, 'Date']
min_mom_pct = df['MoM_Pct'].min()
min_mom_pct_idx = df['MoM_Pct'].idxmin()
min_mom_pct_date = df.loc[min_mom_pct_idx, 'Date']

# Year-over-year changes
df['YoY'] = df['Price'] - df['Price'].shift(12)
df['YoY_Pct'] = df['Price'].pct_change(12) * 100

# ── Decade Analysis ──────────────────────────────────────────────────────────

decades = df.groupby('Decade').agg(
    Avg_Price=('Price', 'mean'),
    Median_Price=('Price', 'median'),
    Std_Dev=('Price', 'std'),
    Min_Price=('Price', 'min'),
    Max_Price=('Price', 'max'),
    Count=('Price', 'count')
).reset_index()

decade_with_highest_avg = decades.loc[decades['Avg_Price'].idxmax()]

# ── Yearly summary for CAGR chart ────────────────────────────────────────────

yearly = df.groupby('Year').agg(
    Avg_Price=('Price', 'mean'),
    Min_Price=('Price', 'min'),
    Max_Price=('Price', 'max')
).reset_index()

# ── Major events annotation ──────────────────────────────────────────────────

events = [
    {'label': '1973 Oil Embargo', 'year': 1973.8, 'price': 4.1, 'note': 'Prices surged from ~$2 to $13'},
    {'label': '1979 Iranian Revolution', 'year': 1979.3, 'price': 16.0, 'note': 'Second oil shock'},
    {'label': '1986 Price Collapse', 'year': 1986.5, 'price': 10.0, 'note': 'OPEC quota collapse; prices fell 60%+ in months'},
    {'label': '1990 Gulf War', 'year': 1990.7, 'price': 36.0, 'note': 'Brief spike above $36'},
    {'label': '2008 Financial Crisis', 'year': 2008.5, 'price': 140.0, 'note': 'All-time nominal high of $140/bbl'},
    {'label': '2014–2016 Shale Crash', 'year': 2015.0, 'price': 30.0, 'note': 'Supply glut drove prices below $30'},
    {'label': '2020 COVID-19', 'year': 2020.3, 'price': 16.0, 'note': 'Demand collapse; negative futures'},
    {'label': '2022 Ukraine Invasion', 'year': 2022.3, 'price': 100.0, 'note': 'Prices breached $110 post-invasion'},
]

# ── Build chart data as JSON for JS ──────────────────────────────────────────

monthly_chart_data = {
    'dates': df['Date'].dt.strftime('%Y-%m-%d').tolist(),
    'prices': [round(x, 2) for x in df['Price'].tolist()],
}

decade_chart_data = {
    'labels': [f"{int(d)}s" for d in decades['Decade'].tolist()],
    'avg': [round(x, 2) for x in decades['Avg_Price'].tolist()],
    'std': [round(x, 2) for x in decades['Std_Dev'].tolist()],
    'min': [round(x, 2) for x in decades['Min_Price'].tolist()],
    'max': [round(x, 2) for x in decades['Max_Price'].tolist()],
}

mom_chart = {
    'dates': df['Date'].dt.strftime('%Y-%m-%d').tolist()[1:],
    'mom_abs': [round(x, 2) if not pd.isna(x) else 0 for x in df['MoM_Abs'].tolist()[1:]],
    'mom_pct': [round(x, 2) if not pd.isna(x) else 0 for x in df['MoM_Pct'].tolist()[1:]],
}

yoy_chart = {
    'dates': df['Date'].dt.strftime('%Y-%m-%d').tolist()[12:],
    'yoy_pct': [round(x, 2) if not pd.isna(x) else 0 for x in df['YoY_Pct'].tolist()[12:]],
}

distribution_data = {
    'prices': [round(x, 2) for x in df['Price'].tolist()],
}

# Decade price bands for bar chart
decade_bands = []
for _, row in decades.iterrows():
    d = int(row['Decade'])
    sub = df[df['Decade'] == d]['Price']
    decade_bands.append({
        'label': f"{d}s",
        'avg': round(row['Avg_Price'], 2),
        'min': round(row['Min_Price'], 2),
        'max': round(row['Max_Price'], 2),
        'std': round(row['Std_Dev'], 2),
        'count': int(row['Count']),
    })

# Yearly for trend chart
yearly_chart_data = {
    'years': yearly['Year'].tolist(),
    'avg': [round(x, 2) for x in yearly['Avg_Price'].tolist()],
    'min': [round(x, 2) for x in yearly['Min_Price'].tolist()],
    'max': [round(x, 2) for x in yearly['Max_Price'].tolist()],
}

# ── Decade narrative text ────────────────────────────────────────────────────

decade_narratives = {
    1970: {
        'title': '1970s — The Oil Shocks Era',
        'text': (
            f'The 1970s transformed global energy markets. Prices averaged <strong>${decades[decades["Decade"]==1970]["Avg_Price"].values[0]:.2f}</strong>/bbl, '
            f'starting at ${df[df["Decade"]==1970]["Price"].min():.2f} before the 1973 embargo sent prices soaring to '
            f'${df[df["Decade"]==1970]["Price"].max():.2f} by decade\'s end. The 1973 Arab oil embargo quadrupled prices, '
            f'and the 1979 Iranian Revolution triggered the second oil shock. Volatility was extreme: '
            f'standard deviation of ${decades[decades["Decade"]==1970]["Std_Dev"].values[0]:.2f} — unprecedented at the time.'
        )
    },
    1980: {
        'title': '1980s — Boom, Bust & Stabilization',
        'text': (
            f'Average price: <strong>${decades[decades["Decade"]==1980]["Avg_Price"].values[0]:.2f}</strong>/bbl. '
            f'The decade opened near crisis-era highs (~${df[(df["Decade"]==1980) & (df["Year"]==1980)]["Price"].max():.2f}) '
            f'before the 1986 price collapse sent crude below ${df[df["Decade"]==1980]["Price"].min():.2f}. '
            f'OPEC\'s quota discipline crumbled, and Saudi Arabia abandoned its swing-producer role, flooding the market. '
            f'By the late 1980s, prices stabilized around $15–20/bbl — a new equilibrium that would define the next era.'
        )
    },
    1990: {
        'title': '1990s — Low & Stable Prices',
        'text': (
            f'The most placid decade on record. Average price: <strong>${decades[decades["Decade"]==1990]["Avg_Price"].values[0]:.2f}</strong>/bbl '
            f'with a standard deviation of just ${decades[decades["Decade"]==1990]["Std_Dev"].values[0]:.2f}. '
            f'The 1990 Gulf War caused a brief spike to ${df[df["Decade"]==1990]["Price"].max():.2f}, but prices quickly retreated. '
