</footer>

<script>
const accent = '#f59e0b';
const accent2 = '#3b82f6';
const red = '#ef4444';
const green = '#22c55e';
const muted = '#94a3b8';
const gridColor = 'rgba(148,163,184,0.1)';
const textColor = '#e2e8f0';

Chart.defaults.color = muted;
Chart.defaults.borderColor = gridColor;
Chart.defaults.plugins.legend.labels.color = textColor;

// 1. Monthly time series
{
  const d = """ + monthly_json + """;
  const ctx = document.getElementById('monthlyChart').getContext('2d');
  new Chart(ctx, {{
    type: 'line',
    data: {{
      labels: d.dates,
      datasets: [{{
        label: 'Crude Oil Price (USD/bbl)',
        data: d.prices,
        borderColor: accent,
        backgroundColor: 'rgba(245,158,11,0.08)',
        borderWidth: 1.5,
        pointRadius: 0,
        fill: true,
        tension: 0.1
      }}]
    }},
    options: {{
      responsive: true,
      maintainAspectRatio: false,
      plugins: {{
        tooltip: {{
          callbacks: {{
            label: ctx => '$' + ctx.parsed.y.toFixed(2) + '/bbl'
          }}
        }},
        annotation: {{}}
      }},
      scales: {{
        x: {{
          type: 'time',
          time: {{ unit: 'year', displayFormats: {{ year: 'yyyy' }} }},
          ticks: {{ maxTicksLimit: 30 }},
          grid: {{ display: false }}
        }},
        y: {{
          title: {{ display: true, text: 'USD per barrel', color: muted }},
          ticks: {{ callback: v => '$' + v }}
        }}
      }}
    }}
  }});
}}

// 2. Decade bar chart with error bands
{
  const d = """ + decade_bands_json + """;
  const ctx = document.getElementById('decadeBarChart').getContext('2d');
  new Chart(ctx, {{
    type: 'bar',
    data: {{
      labels: d.map(x => x.label),
      datasets: [
        {{
          label: 'Avg Price (USD/bbl)',
          data: d.map(x => x.avg),
          backgroundColor: 'rgba(245,158,11,0.7)',
          borderColor: accent,
          borderWidth: 1,
          order: 2
        }},
        {{
          label: 'Min Price',
          data: d.map(x => x.min),
          backgroundColor: 'rgba(59,130,246,0.4)',
          borderColor: accent2,
          borderWidth: 1,
          order: 1
        }},
        {{
          label: 'Max Price',
          data: d.map(x => x.max),
          backgroundColor: 'rgba(239,68,68,0.4)',
          borderColor: red,
          borderWidth: 1,
          order: 1
        }}
      ]
    }},
    options: {{
      responsive: true,
      maintainAspectRatio: false,
      plugins: {{
        tooltip: {{ callbacks: {{ label: ctx => ctx.dataset.label + ': $' + ctx.parsed.y.toFixed(2) }} }}
      }},
      scales: {{
        y: {{
          title: {{ display: true, text: 'USD per barrel', color: muted }},
          ticks: {{ callback: v => '$' + v }}
        }}
      }}
    }}
  }});
}}

// 3. Decade volatility (avg + std dev error bars)
{
  const d = """ + decade_json + """;
  const ctx = document.getElementById('decadeVolatilityChart').getContext('2d');
  new Chart(ctx, {{
    type: 'bar',
    data: {{
      labels: d.labels,
      datasets: [{{
        label: 'Average Price',
        data: d.avg,
        backgroundColor: 'rgba(245,158,11,0.6)',
        borderColor: accent,
        borderWidth: 1,
        errorBars: d.std.map((v, i) => ({{ plus: v, minus: v }}))
      }}]
    }},
    options: {{
      responsive: true,
      maintainAspectRatio: false,
      plugins: {{
        tooltip: {{ callbacks: {{ label: ctx => 'Avg: $' + ctx.parsed.y.toFixed(2) + ' ± ' + d.std[ctx.dataIndex].toFixed(2) }} }}
      }},
      scales: {{
        y: {{
          title: {{ display: true, text: 'USD per barrel', color: muted }},
          ticks: {{ callback: v => '$' + v }}
        }}
      }}
    }}
  }});
}}

// 4. Month-over-month absolute changes
{
  const d = """ + mom_json + """;
  const ctx = document.getElementById('momChart').getContext('2d');
  new Chart(ctx, {{
    type: 'bar',
    data: {{
      labels: d.dates,
      datasets: [{{
        label: 'MoM Price Change ($)',
        data: d.mom_abs,
        backgroundColor: d.mom_abs.map(v => v >= 0 ? 'rgba(34,197,94,0.5)' : 'rgba(239,68,68,0.5)'),
        borderColor: d.mom_abs.map(v => v >= 0 ? green : red),
        borderWidth: 0.5,
        pointRadius: 0
      }}]
    }},
    options: {{
      responsive: true,
      maintainAspectRatio: false,
      plugins: {{
        tooltip: {{ callbacks: {{ label: ctx => '$' + ctx.parsed.y.toFixed(2) }} }}
      }},
      scales: {{
        x: {{ ticks: {{ maxTicksLimit: 30 }}, grid: {{ display: false }} }},
        y: {{ title: {{ display: true, text: 'USD per barrel change', color: muted }} }}
      }}
    }}
  }});
}}

// 5. Year-over-year percentage changes
{
  const d = """ + yoy_json + """;
  const ctx = document.getElementById('yoyChart').getContext('2d');
  new Chart(ctx, {{
    type: 'bar',
    data: {{
      labels: d.dates,
      datasets: [{{
        label: 'YoY Price Change (%)',
        data: d.yoy_pct,
        backgroundColor: d.yoy_pct.map(v => v >= 0 ? 'rgba(34,197,94,0.5)' : 'rgba(239,68,68,0.5)'),
        borderColor: d.yoy_pct.map(v => v >= 0 ? green : red),
        borderWidth: 0.5
      }}]
    }},
    options: {{
      responsive: true,
      maintainAspectRatio: false,
      plugins: {{
        tooltip: {{ callbacks: {{ label: ctx => ctx.parsed.y.toFixed(1) + '%' }} }}
      }},
      scales: {{
        x: {{ ticks: {{ maxTicksLimit: 30 }}, grid: {{ display: false }} }},
        y: {{ title: {{ display: true, text: 'Percent change', color: muted }}, ticks: {{ callback: v => v + '%' }} }}
      }}
    }}
  }});
}}

