          borderWidth: 0,
          type: 'line',
          fill: false,
          pointRadius: 0,
          order: 1
        }}
      ]
    }},
    options: {{
      responsive: true,
      maintainAspectRatio: false,
      plugins: {{ tooltip: {{ callbacks: {{ label: ctx => '$' + ctx.parsed.y.toFixed(2) }} }} }},
      scales: {{
        x: {{ ticks: {{ maxTicksLimit: 30 }} }},
        y: {{ title: {{ display: true, text: 'USD per barrel', color: muted }}, ticks: {{ callback: v => '$' + v }} }}
